public T getParsedOptionValue(final Option option, final Supplier<T> defaultValue) throws ParseException  {
    if (option == null)
    {
        return get(defaultValue);
    }
    final String res = getOptionValue(option);
    try
    {
        if (res == null)
        {
            return get(defaultValue);
        }
