public static final byte[] decodeQuotedPrintable(final byte[] bytes) throws DecoderException  {
    if (bytes == null)
    {
        return null;
    }
    final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    for (int i = 0;
    i < bytes.length;
    i++)
    {
        final int b = bytes[i];
        if (b == ESCAPE_CHAR)
        {
            try
            {
                // if the next octet is a CR we have found a soft line break if (bytes[++i] == CR)
                {
                    continue;
                }
                final int u = Utils.digit16(bytes[i]);
                final int l = Utils.digit16(bytes[++i]);
                buffer.write((char) ((u << 4) + l));
            }
            catch (final ArrayIndexOutOfBoundsException e)
            {
                throw new DecoderException("Invalid quoted-printable encoding", e);
            }
        }
        else if (b != CR && b != LF)
        {
            // every other octet is appended except for CR & LF buffer.write(b);
        }
    }
    return buffer.toByteArray();
}
