public static final byte[] decodeQuotedPrintable(final byte[] bytes) throws DecoderException  {
    if (bytes == null)
    {
        return null;
    }
    final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    for (int i = 0;
    i < bytes.length;
    i++)
    {
        final int b = bytes[i];
        if (b == ESCAPE_CHAR)
