                    continue;
                }
                final int u = Utils.digit16(bytes[i]);
                final int l = Utils.digit16(bytes[++i]);
                buffer.write((char) ((u << 4) + l));
            }
            catch (final ArrayIndexOutOfBoundsException e)
            {
