            final int b = getUnsignedOctet(i, bytes);
            if (pos < SAFE_LENGTH)
            {
                // up to this length it is safe to add any byte, encoded or not pos += encodeByte(b, !printable.get(b), buffer);
            }
            else
            {
                // rule #3: whitespace at the end of a line *must* be encoded encodeByte(b, !printable.get(b) || isWhitespace(b), buffer);
                // rule #5: soft line break buffer.write(ESCAPE_CHAR);
                buffer.write(CR);
                buffer.write(LF);
                pos = 1;
            }
        }
        // rule #3: whitespace at the end of a line *must* be encoded // if we would do a soft break line after this octet, encode whitespace int b = getUnsignedOctet(bytesLength - 3, bytes);
